unordered_map<int, int> freq;
int distinct = 0;

for (int r = 0; r < n; r++) {

    // A value becomes distinct when count changes 0 -> 1
    if (++freq[arr[r]] == 1) {
        distinct++;
    }

    // Value disappears when count changes 1 -> 0
    if (r >= k) {
        if (--freq[arr[r - k]] == 0) {
            distinct--;
        }
    }

    if (r >= k - 1) {
        // `distinct` is the number of unique values
        // in the current window
    }
}
```
